function minSpeed(jobs, hours) {
  const hoursAt = (s) => {
    let total = 0
    for (const p of jobs) total += Math.ceil(p / s)
    return total
  }
  let lo = 1
  let hi = Math.max(...jobs)
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2)
    if (hoursAt(mid) <= hours) hi = mid
    else lo = mid + 1
  }
  return lo
}

