        return sum((p + s - 1) // s for p in jobs)

    lo, hi = 1, max(jobs)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if hours_at(mid) <= hours:
            hi = mid
        else:
            lo = mid + 1
    return lo

